#define MB_HASH_ALGORITHM_SHA3_256   0x0aU /*  */
#define MB_HASH_ALGORITHM_SHA3_384   0x0bU /*  */
#define MB_HASH_ALGORITHM_SHA3_512   0x0cU /*  */

/* struct hash, HASH算法命令。 */
typedef struct {
    uint16_t cmd_id;        /* [offset: 0] 0x0301 */
    uint16_t cmd_id_inv;    /* [offset: 2] cmd_id取反 */
    uint8_t reserved0[8];   /* [offset: 4] reserved */
    uint8_t process_mode;   /* [offset: 12] 处理模式。 */
    uint8_t reserved1[2];   /* [offset: 13] reserved */
    uint8_t algorithm;      /* [offset: 15] 哈希算法类型。 */
    uint8_t reserved2[20];  /* [offset: 16] reserved */
    raddr_t data;           /* [offset: 36] 用于生成哈希值的消息数据的地址。 */
    uint32_t data_size;     /* [offset: 44] 消息数据的长度。 */
    raddr_t digest;         /* [offset: 48] 用于存储HASH值的地址 */
    uint32_t digest_size;   /* [offset: 56] HASH缓冲区的长度 */
    uint8_t reserved3[12];  /* [offset: 60] reserved */
    raddr_t hash_ctx;       /* [offset: 72] HASH上下文的地址。 */
    uint32_t hash_ctx_size; /* [offset: 80] 上下文的长度。 */
} mb_cmd_hash_st;

/* response struct */
typedef struct {
    uint32_t ret_code;    /* [offset: 0] 0x0000A55AU 表示操作成功, 其它值表示失败. */
    uint32_t digest_size; /* [offset: 4] 输出HASH值的大小 */
} mb_rsp_hash_st;

/* ---- command hash end ---- */

