#define MB_MAC_CIPHER_MODE_GMAC    0x09U /*  */

/* struct mac, MAC 生成或验证命令。 */
typedef struct {
    uint16_t cmd_id;         /* [offset: 0] 0x0201 */
    uint16_t cmd_id_inv;     /* [offset: 2] cmd_id取反 */
    uint8_t reserved0[7];    /* [offset: 4] reserved */
    uint8_t key_type;        /* [offset: 11] 密钥类型 */
    uint8_t process_mode;    /* [offset: 12] 处理模式。 */
    uint8_t direction;       /* [offset: 13] MAC 方向。 */
    uint8_t reserved1[1];    /* [offset: 14] reserved */
    uint8_t algorithm;       /* [offset: 15] MAC 使用的对称算法。 */
    uint8_t cipher_mode;     /* [offset: 16] MAC加密模式。 */
    uint8_t reserved2[3];    /* [offset: 17] reserved */
    uint32_t key_handle;     /* [offset: 20] 用于生成/验证 MAC 的密钥。 */
    uint8_t reserved3[12];   /* [offset: 24] reserved */
    raddr_t data;            /* [offset: 36] 用于生成/验证 MAC 的消息数据的地址。 */
    uint32_t data_size;      /* [offset: 44] 消息数据的长度。 */
    raddr_t mac;             /* [offset: 48] 生成或验证后的 MAC 值的地址。 */
    uint32_t mac_size;       /* [offset: 56] MAC 缓冲区的长度或生成的 MAC 值的长度。 */
    raddr_t iv_addr;         /* [offset: 60] GMAC 的 IV 地址。仅支持 GMAC，且大小应为 12 字节。 */
    uint8_t reserved4[4];    /* [offset: 68] reserved */
    raddr_t mac_ctx;         /* [offset: 72] MAC 的上下文地址。 */
    uint32_t mac_ctx_size;   /* [offset: 80] 上下文的长度。 */
    raddr_t plain_key_addr;  /* [offset: 84] 明文密钥，key_type为1时有效。 */
    uint32_t plain_key_size; /* [offset: 92] 明文密钥长度，key_type为1时有效。 */
} mb_cmd_mac_st;

/* response struct */
typedef struct {
    uint32_t ret_code;     /* [offset: 0] 0x0000A55AU 表示操作成功, 其它值表示失败. */
    uint32_t mac_size;     /* [offset: 4] 输出 MAC 的大小。 */
    uint32_t verification; /* [offset: 8] 验证结果。0 表示成功，其他表示失败。生成 MAC 时忽略。 */
} mb_rsp_mac_st;

