    raddr_t sign_addr;      /* [offset: 48] 签名值的地址。 */
    uint32_t sign_size;     /* [offset: 56] 签名缓冲区或签名值的大小。 */
    uint8_t reserved3[12];  /* [offset: 60] reserved */
    raddr_t sign_ctx;       /* [offset: 72] 签名或验证的上下文地址。 */
    uint32_t sign_ctx_size; /* [offset: 80] 上下文的长度。 */
