#define MB_CMD_ID_SM9_CIPHER 0x0701U /* Command ID for sm9_cipher*/

/* struct sm9_cipher, SM9 加解密命令。 */
typedef struct {
    uint16_t cmd_id;      /* [offset: 0] 0x0701 */
    uint16_t cmd_id_inv;  /* [offset: 2] cmd_id取反 */
    uint8_t reserved0[7]; /* [offset: 4] reserved */
    uint8_t key_type;     /* [offset: 11] 密钥类型 */
    uint8_t enc_type;     /* [offset: 12] SM9 的内部加密模式。 */
    uint8_t direction;    /* [offset: 13] 加密方向。 */
    uint8_t padding_type; /* [offset: 14] 填充模式，仅在 enc_type 为 `SM9-ENC-TYPE-SM4` 时有效 */
    uint8_t key2_size;    /* [offset: 15] 内部 MAC 算法密钥的字节长度。 */
    uint8_t reserved1[2]; /* [offset: 16] reserved */
    uint8_t hid;          /* [offset: 18] 私钥生成函数标识符，由 KGC 选择并披露。 */
    uint8_t reserved2[1]; /* [offset: 19] reserved */
    uint32_t key_handle;  /* [offset: 20] SM9 密钥的句柄，用于加密，，当key_type为0时有效。 */
    raddr_t kgc_pub_key;  /* [offset: 24] KGC master公钥的地址，此公钥大小为 64 字节。解密模式中忽略。 */
    uint8_t reserved3[4]; /* [offset: 32] reserved */
    raddr_t input_addr;   /* [offset: 36] 输入数据的地址。 */
    uint32_t input_size;  /* [offset: 44] 输入数据的字节数，必须小于 1024。 */
    raddr_t output_addr;  /* [offset: 48] 输出数据的地址。 */
    uint32_t output_size; /* [offset: 56] 输出数据缓部区的长度。 */
    raddr_t id_addr;      /* [offset: 60] 用户 ID 的地址。 */
    uint32_t id_size;     /* [offset: 68] 加密接收方用户 ID 的大小，最大为 1024 字节。 */
    raddr_t fp12g; /* [offset: 72] e(P1, pub_key) 的值的地址，如果设置为 NULL，将在 eHSM 中计算，fp12g 的大小为 384
                      字节。 */
    raddr_t plain_key_addr; /* [offset: 80] 明文密钥，key_type为1时有效。 */
} mb_cmd_sm9_cipher_st;

/* response struct */
typedef struct {
    uint32_t ret_code;    /* [offset: 0] 0x0000A55AU 表示操作成功, 其它值表示失败. */
    uint32_t output_size; /* [offset: 4] 输出明文或密文的大小 */
} mb_rsp_sm9_cipher_st;

