#define MB_CMD_ID_EHSM_GEN_KEY 0x080dU /* Command ID for ehsm_gen_key*/

/* struct ehsm_gen_key, 生成对称和非对称密钥命令。 */
typedef struct {
    uint16_t cmd_id;      /* [offset: 0] 0x080d */
    uint16_t cmd_id_inv;  /* [offset: 2] cmd_id取反 */
    uint8_t reserved0[8]; /* [offset: 4] reserved */
    uint8_t algo_id;      /* [offset: 12] 生成密钥的算法ID。 */
    uint8_t reserved1[3]; /* [offset: 13] reserved */
    uint16_t
        rsa_e_bit_size;   /* [offset: 16]
                             RSA公钥e的位长度。最大为64。当公钥的位长度为17时，输出的公钥e值固定为65537（0x10001）。仅对生成RSA密钥有效。
                           */
    uint16_t key_size;    /* [offset: 18] 创建密钥的长度。仅对生成HMAC密钥有效，最大长度为512字节。 */
    uint32_t key_handle;  /* [offset: 20] 生成密钥的密钥句柄，设置为0xFFFFFFFF表示由密钥管理服务分配的句柄。 */
    uint32_t permit;      /* [offset: 24] 生成的新密钥的权限值。密钥可以有多个权限。 */
    uint8_t reserved2[4]; /* [offset: 28] reserved */
    raddr_t
        dh_common_addr;      /* [offset: 32] DH公共数据的地址。其数据格式为{p_len + p_value + q_len + q_value + g_len +
                                g_value + h_len +
                                h_value}。x_len的值表示x_value值的长度。h_value是可选的，将h_len的值设置为0表示h_value不存在。x_len的长度为4字节。仅对生成DH密钥有效。
                              */
    uint32_t dh_common_size; /* [offset: 40] DH公共数据的长度。仅对生成DH密钥有效，最大长度为2064字节。 */
} mb_cmd_ehsm_gen_key_st;

/* response struct */
typedef struct {
    uint32_t ret_code;   /* [offset: 0] 0x0000A55AU 表示操作成功, 其它值表示失败. */
    uint32_t key_handle; /* [offset: 4] 返回的密钥句柄。 */
} mb_rsp_ehsm_gen_key_st;

