#define MB_CMD_ID_EHSM_KEY_DERIVE 0x080eU /* Command ID for ehsm_key_derive*/

#define MB_EHSM_KEY_DERIVE_KEY_DERIV_FUNC_KDFX963                    0x01U /* KDFX963算法 */
#define MB_EHSM_KEY_DERIVE_KEY_DERIV_FUNC_PBKDF2                     0x02U /* PBKDF2算法 */
#define MB_EHSM_KEY_DERIVE_DERIVE_TYPE_KMS_KEY_DERIVE_USER_PASSWD    0x01U /* 使用用户密码派生密钥 */
#define MB_EHSM_KEY_DERIVE_DERIVE_TYPE_KMS_KEY_DERIVE_USER_KEYHANDLE 0x02U /* 使用用户父密钥派生密钥 */
#define MB_EHSM_KEY_DERIVE_HASH_ALG_SM3                              0x00U /* SM3算法 */
#define MB_EHSM_KEY_DERIVE_HASH_ALG_MD5                              0x01U /* MD5算法 */
#define MB_EHSM_KEY_DERIVE_HASH_ALG_SHA256                           0x02U /* SHA-256算法 */
#define MB_EHSM_KEY_DERIVE_HASH_ALG_SHA384                           0x03U /* SHA-384算法 */
#define MB_EHSM_KEY_DERIVE_HASH_ALG_SHA512                           0x04U /* SHA-512算法 */
#define MB_EHSM_KEY_DERIVE_HASH_ALG_SHA1                             0x05U /* SHA-1算法 */
#define MB_EHSM_KEY_DERIVE_HASH_ALG_SHA224                           0x06U /* SHA-224算法 */
#define MB_EHSM_KEY_DERIVE_HASH_ALG_SHA512_224                       0x07U /* SHA-512/224算法 */
#define MB_EHSM_KEY_DERIVE_HASH_ALG_SHA512_256                       0x08U /* SHA-512/256算法 */
#define MB_EHSM_KEY_DERIVE_HASH_ALG_SHA3_224                         0x09U /* SHA3-224算法 */
#define MB_EHSM_KEY_DERIVE_HASH_ALG_SHA3_256                         0x0aU /* SHA3-256算法 */
#define MB_EHSM_KEY_DERIVE_HASH_ALG_SHA3_384                         0x0bU /* SHA3-384算法 */
#define MB_EHSM_KEY_DERIVE_HASH_ALG_SHA3_512                         0x0cU /* SHA3-512算法 */
#define MB_EHSM_KEY_DERIVE_KEY_OUT_DIR_KEY_DERIVE_OUTPUT_TO_KMS      0x01U /* 密钥将存储在eHSM KMS中 */
#define MB_EHSM_KEY_DERIVE_KEY_OUT_DIR_KEY_DERIVE_OUTPUT_TO_SOC      0x02U /* 密钥将通过硬件安全通道输出到SOC */

/* struct ehsm_key_derive, 密钥派生命令。 */
typedef struct {
    uint16_t cmd_id;            /* [offset: 0] 0x080e */
    uint16_t cmd_id_inv;        /* [offset: 2] cmd_id取反 */
    uint8_t reserved0[8];       /* [offset: 4] reserved */
    uint8_t key_deriv_func;     /* [offset: 12] 密钥派生的函数标识符。 */
    uint8_t reserved1[1];       /* [offset: 13] reserved */
    uint8_t derive_type;        /* [offset: 14] 密钥派生类型。 */
    uint8_t hash_alg;           /* [offset: 15] 密钥派生的哈希算法。 */
    uint8_t algo_id;            /* [offset: 16] 派生密钥的密钥算法ID。注意：仅对称密钥算法ID有效。 */
    uint8_t key_out_dir;        /* [offset: 17] 密钥输出方向。 */
    uint8_t soc_sp_id;          /* [offset: 18] 指示派生密钥数据输出到哪个SOC安全端口索引，当 key_out_dir 为
                                   KEY_DERIVE_OUTPUT_TO_SOC 时有效。 */
    uint8_t reserved2[1];       /* [offset: 19] reserved */
    uint32_t key_handle;        /* [offset: 20] 派生密钥的密钥句柄，如果已存在则覆盖。0xFFFFFFFF值表示自动分配句柄。 */
    uint32_t permit;            /* [offset: 24] 派生密钥的权限值。密钥可以有多个权限位组合。 */
    uint8_t reserved3[4];       /* [offset: 28] reserved */
    uint32_t parent_key_handle; /* [offset: 32] 密钥派生的父密钥，当derive_type为KMS_KEY_DERIVE_USER_PASSWD时忽略 */
    raddr_t salt_data_addr;     /* [offset: 36] 盐数据的host地址。 */
    uint32_t salt_data_size;    /* [offset: 44] 派生密钥的盐参数。最大长度为128字节。 */
    raddr_t pw_data_addr;  /* [offset: 48] 密码数据的host地址。当derive_type为KMS_KEY_DERIVE_USER_KEYHANDLE时忽略。 */
    uint32_t pw_data_size; /* [offset: 56] 派生密钥的密码参数。最大长度为128字节。 */
    uint8_t reserved4[20]; /* [offset: 60] reserved */
    uint32_t itera_times;  /* [offset: 80] 迭代次数，仅对PBKDF2有效，过低的迭代次数影响安全性。 */
    uint8_t reserved5[8];  /* [offset: 84] reserved */
    uint16_t
        key_size; /* [offset: 92]
                     派生密钥的字节大小。如果算法ID是HMAC密钥，则最大大小为512字节。其他算法ID必须设置为与算法要求相匹配。
                   */
} mb_cmd_ehsm_key_derive_st;

/* response struct */
typedef struct {
    uint32_t ret_code;   /* [offset: 0] 0x0000A55AU 表示操作成功, 其它值表示失败. */
    uint32_t key_handle; /* [offset: 4] 返回的密钥句柄。 */
} mb_rsp_ehsm_key_derive_st;

