    uint32_t dh_commom_size; /* [offset: 40] DH公共数据的长度。仅对生成DH密钥有效。最大大小为2064字节。 */
    raddr_t remote_pubkey_data;  /* [offset: 44] 远程公钥数据的host地址。 */
    uint32_t remote_pubkey_size; /* [offset: 52] 远程公钥的大小。最大大小为512字节。 */
    uint8_t reserved3[12];       /* [offset: 56] reserved */
