    uint32_t self_id_size;     /* [offset: 44] 自身ID的字节大小，最大可以为1024。 */
    raddr_t s1_s2_addr;        /* [offset: 48] S1（或S2）验证值的地址，大小为32。 */
    raddr_t sa_sb_addr;        /* [offset: 56] SA（或SB）验证值的地址，大小为32。 */
