    uint8_t reserved2[4];          /* [offset: 28] reserved */
    raddr_t other_info;            /* [offset: 32] SM9密钥交换的其他信息。 */
    uint32_t user_tmp_key_handle;  /* [offset: 40] SM9密钥交换的本地临时密钥。 */
    uint8_t reserved3[4];          /* [offset: 44] reserved */
